using HRIS.Api.Common; using HRIS.Api.DTOs.Family; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Models.Enums; using HRIS.Api.Repositories;
namespace HRIS.Api.Services; public class FamilyChangeService : IFamilyChangeService { private readonly IFamilyChangeRepository _repo; private readonly IReferenceRepository _refs; private readonly IApprovalService _approval; private readonly IEmployeeRepository _employees; public FamilyChangeService(IFamilyChangeRepository repo,IReferenceRepository refs,IApprovalService approval,IEmployeeRepository employees){_repo=repo;_refs=refs;_approval=approval;_employees=employees;} public async Task<List<FamilyChangeResponseDto>> GetAsync(UserContext actor){var rows=await _repo.GetAllAsync(actor.IsHrOrSupport?null:actor.EmployeeId);var approvals=await _approval.GetByRefsAsync(ApprovalRequestTypes.FamilyChange,rows.Select(x=>x.Id),actor);return rows.Select(x=>ToDto(x,approvals.GetValueOrDefault(x.Id)?.Id)).ToList();} public async Task<FamilyChangeResponseDto> CreateAsync(FamilyChangeCreateDto dto,UserContext actor){var emp=actor.EmployeeId??throw new ForbiddenException("Akun ini tidak terhubung ke Employee."); var employee=await _employees.GetByIdAsync(emp)??throw new NotFoundException("Employee tidak ditemukan."); var currentEmployment=employee.Employments.FirstOrDefault(x=>x.EndDate==null); if(currentEmployment is not null && !await _refs.IsModuleAllowedAsync(currentEmployment.EmploymentTypeId,"3")) throw new ForbiddenException("Karyawan dengan tipe pekerjaan saat ini tidak mendapatkan modul Benefit."); var action=dto.Action.Trim(); if(!new[]{"Add","Update","Delete"}.Contains(action,StringComparer.OrdinalIgnoreCase)) throw new BadRequestException("Action harus Add, Update, atau Delete."); if(dto.FamilyId is not null){if(await _repo.GetFamilyAsync(emp,dto.FamilyId.Value) is null) throw new BadRequestException("FamilyId tidak ditemukan untuk karyawan ini.");} else if(!action.Equals("Add",StringComparison.OrdinalIgnoreCase)) throw new BadRequestException("FamilyId wajib untuk Update/Delete."); if(!await _refs.ExistsAsync<Relationship>(dto.RelationshipId)) throw new BadRequestException("RelationshipId tidak ditemukan."); if(dto.GenderId is not null&&!await _refs.ExistsAsync<Gender>(dto.GenderId.Value)) throw new BadRequestException("GenderId tidak ditemukan."); if(action.Equals("Add",StringComparison.OrdinalIgnoreCase)&&string.IsNullOrWhiteSpace(dto.FamilyName)) throw new BadRequestException("Nama keluarga wajib diisi."); var x=new FamilyChangeRequest{EmployeeId=emp,FamilyId=dto.FamilyId,Action=action,FamilyName=dto.FamilyName.Trim(),RelationshipId=dto.RelationshipId,GenderId=dto.GenderId,BirthDate=dto.BirthDate,IsDependent=dto.IsDependent,WeddingDate=dto.WeddingDate,Status="Pending"}; await _repo.AddAsync(x); var approval=await _approval.SubmitAsync(ApprovalRequestTypes.FamilyChange,x.Id,emp,$"{action} data keluarga: {x.FamilyName}"); return ToDto(await _repo.GetByIdAsync(x.Id)!,approval.Id);} public Task ApplyApprovedAsync(int id)=>Task.CompletedTask; private static FamilyChangeResponseDto ToDto(FamilyChangeRequest x,int? approvalId)=>new(){Id=x.Id,EmployeeId=x.EmployeeId,EmployeeName=x.Employee?.FullName??"",FamilyId=x.FamilyId,Action=x.Action,FamilyName=x.FamilyName,RelationshipId=x.RelationshipId,RelationshipName=x.Relationship?.RelationshipName??"",GenderId=x.GenderId,GenderName=x.Gender?.GenderName,BirthDate=x.BirthDate,IsDependent=x.IsDependent,WeddingDate=x.WeddingDate,Status=x.Status,ApprovalId=approvalId}; }
